const previewRoute=location.pathname==='/local/preview.html';
if(previewRoute){const originalFetch=window.fetch.bind(window);window.fetch=(input,options)=>{if(typeof input==='string'&&/^\/api\/local\/(launch|businesses|lead|metric)(?:[?]|$)/.test(input)){const u=new URL(input,location.origin);u.searchParams.set('preview','1');input=u.pathname+u.search;}return originalFetch(input,options);};document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&a.pathname==='/local'){e.preventDefault();location.hash=a.hash||'/';}},true);}
import {icon,categoryIconNames} from './ui-icons.js';
import {favorites,toggleFavorite,savedKey,readLocal,receiptKey} from './local-state.js';
import {sectors} from './sector-config.js';
import {sectorActions,sectorCatalog} from './sector-flows.js?v=20260928-launch';
const main=document.querySelector('main');
const cats=['Para você',...sectors.filter(x=>x!=='Outro')];
let saved=favorites();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(n,label,extra='')=>`<div class="photo p${n} ${extra}" role="img" aria-label="${esc(label)}"></div>`;
const link=id=>`/local#/${id}`;
const cards=list=>list.length?`<div class="grid">${list.map(i=>`<article class="card${i.real?' real-card':''}"><a href="${i.href||(i.real?'/local#/negocio?id='+encodeURIComponent(i.id):link(i.id))}">${i.real?(i.image?`<img class="photo real-card-photo" src="${esc(i.image)}" alt="${esc(i.name)}" loading="lazy">`:'<div class="photo real-card-placeholder"><span>helpu <small>LOCAL</small></span></div>'):photo(i.photo,i.name)}<div class="card-body"><small>${esc(i.cat)}</small><h3>${i.logo?`<img class="business-logo card-business-logo" src="${esc(i.logo)}" alt="${esc(i.name)}" loading="lazy">`:esc(i.title)}</h3><p>${esc(i.real?i.desc:i.name)}</p><span class="text-link">${esc(i.cta)} <span data-icon="arrow"></span></span></div></a><button class="save" data-save="${esc(i.id)}" aria-label="Salvar ${esc(i.name)}" aria-pressed="${saved.includes(i.id)}">${icon('heart')}</button></article>`).join('')}</div>`:`<div class="empty"><h2>Nenhum resultado por aqui.</h2><p>Explore as categorias e salve os negócios que você quer conhecer.</p><a class="primary" href="/local">Explorar</a></div>`;
const realCard=r=>({id:r.id,real:true,logo:r.logo,image:r.photos?.[0],cat:r.sector,title:r.name,name:r.name,desc:r.description||'',cta:'Conhecer negócio'});
const back=()=>`<a class="back" href="/local">← Voltar para explorar</a>`;
const categoryIcon=c=>icon(categoryIconNames[c]||'grid');
function categoryNavigation(selected,query){
 const primary=['Para você','Gastronomia','Compras','Moda','Serviços','Eventos','Viagens'];
 if(!primary.includes(selected)&&cats.includes(selected))primary[3]=selected;
 const item=c=>`<a class="category-option ${c===selected?'active':''}" href="/local#/categoria?${new URLSearchParams({tipo:c,...query?{q:query}:{}})}" ${c===selected?'aria-current="page"':''}>${categoryIcon(c)}<span>${esc(c)}</span></a>`;
 return `<section class="category-explorer" aria-labelledby="category-heading"><div class="category-heading"><h2 id="category-heading">Explore por categoria</h2><span>Encontre o seu próximo destino.</span></div><nav class="categories" aria-label="Categorias principais">${primary.map(item).join('')}<button type="button" class="category-option category-all" data-all-categories aria-haspopup="dialog">${categoryIcon('Outro')}<span>Ver todas</span></button></nav><dialog class="category-dialog" id="category-dialog" aria-labelledby="all-categories-title"><div class="category-dialog-heading"><div><span class="eyebrow">DESCUBRA VACARIA</span><h2 id="all-categories-title">O que você quer encontrar?</h2></div><button type="button" data-close-categories aria-label="Fechar categorias">×</button></div><nav class="category-directory" aria-label="Todas as categorias">${cats.map(item).join('')}</nav></dialog></section>`;
}
document.addEventListener('click',e=>{if(e.target.closest('[data-all-categories]'))document.querySelector('#category-dialog').showModal();if(e.target.closest('[data-close-categories]')||e.target.closest('#category-dialog a'))document.querySelector('#category-dialog')?.close();if(e.target.id==='category-dialog'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
async function render(){saved=favorites();updateSavedNavigation();const raw=location.hash.slice(2);let [route,query='']=raw.split('?');const params=new URLSearchParams(query);let title='Explore Vacaria';
if(!route||route==='categoria'){const cat=params.get('tipo')||'Para você',q=params.get('q')||'';title=cat==='Para você'?'Explore Vacaria':cat;main.innerHTML=`<section class="hero">${cat==='Para você'?'<img class="local-hero-logo" src="/local/assets/helpu-local-logo.png" alt="Helpu Local" width="2172" height="724" fetchpriority="high">':''}<h1>${cat==='Para você'?'Viva o melhor de <span class="accent">Vacaria.</span>':cat==='Eventos'?'O que acontece em <span class="accent">Vacaria.</span>':`${esc(cat)} em <span class="accent">Vacaria.</span>`}</h1><p>Lugares, produtos, serviços e eventos. Tudo mais perto de você.</p><form class="search" id="search"><label class="sr" for="q">Buscar negócios e eventos</label><input id="q" name="q" value="${esc(q)}" placeholder="O que você procura hoje?" type="search"><input type="hidden" name="tipo" value="${esc(cat)}"><button class="primary" aria-label="Buscar">${icon('search')}</button></form></section>${categoryNavigation(cat,q)}<section id="real-businesses" role="status">Carregando negócios e eventos…</section>`;
}else if(route==='salvos'){title='Seus salvos';main.innerHTML=back()+`<h1 class="page-title">Para conhecer depois.</h1><p class="muted">Seus favoritos ficam salvos neste navegador.</p>`+'<div id="saved-cards" role="status">Carregando seus salvos…</div>';loadSaved();
 }else if(route==='pedidos'){title='Meus pedidos';const receipts=readLocal(receiptKey);main.innerHTML=back()+`<div class="page-intro"><span class="eyebrow">SUAS SOLICITAÇÕES</span><h1 class="page-title">Cada encontro começa aqui.</h1><p class="muted">Pedidos enviados neste navegador. O negócio retorna pelo WhatsApp para confirmar os detalhes.</p></div>${receipts.length?'<div class="receipt-grid">'+receipts.map(x=>`<article class="panel receipt-card"><span class="status-pill">Solicitação enviada</span><h2>${esc(x.businessName)}</h2><p>${esc(x.label)}</p><p class="helper">${new Date(x.at).toLocaleString('pt-BR')}</p><p class="helper">O status final é combinado com a empresa.</p><a class="text-link" href="/local#/negocio?id=${encodeURIComponent(x.businessId)}">Ver negócio ↗</a></article>`).join('')+'</div>':'<div class="empty"><h2>Seu próximo encontro está na cidade.</h2><p>Ao solicitar uma reserva, orçamento ou participação, o registro aparecerá aqui.</p><a href="/local" class="primary">Explorar a cidade ↗</a></div>'}`;
}else if(route==='empresas'){title='Criar conta Helpu Local';location.replace('/local/cadastro.html?tipo=empresa');return;
}else if(route==='negocio'){title='Negócio local';main.innerHTML=back()+'<p role="status">Carregando o negócio…</p>';loadBusiness(params.get('id'));
}else if(route==='evento'){title='Evento';main.innerHTML=back()+'<p role="status">Carregando evento…</p>';loadEvent(params.get('empresa'),params.get('id'));}else{main.innerHTML=back()+'<div class="empty"><h1>Página não encontrada</h1><a href="/local">Voltar ao início</a></div>';}
document.title=title+' · Helpu Local';}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){e.preventDefault();const id=save.dataset.save,result=toggleFavorite(id);saved=result.values;syncSavedButtons();updateSavedNavigation();showLocalToast(result.persisted?(saved.includes(id)?'Salvo para conhecer depois.':'Removido dos salvos.'):'Salvo nesta página. Seu navegador bloqueou o armazenamento permanente.');if(location.hash==='#/salvos')render();}if(e.target.closest('.close,[data-close]'))document.querySelector('dialog').close();});
document.addEventListener('submit',e=>{if(e.target.id==='search'){e.preventDefault();const data=new FormData(e.target);location.hash='/categoria?'+new URLSearchParams(data).toString();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus({preventScroll:true});});render();

async function publicBusinesses(){const r=await fetch('/api/local/businesses',{cache:'no-store'});if(!r.ok)throw new Error('Não foi possível carregar os negócios.');return (await r.json()).businesses;}
async function loadBusiness(id){try{const rows=await publicBusinesses();if(!location.hash.startsWith('#/negocio')||new URLSearchParams(location.hash.split('?')[1]||'').get('id')!==id)return;const r=rows.find(x=>x.id===id);if(!r){main.innerHTML=back()+'<div class="empty"><h1>Esta página não está disponível.</h1></div>';return;}document.title=r.name+' · Helpu Local';main.innerHTML=back()+`<section class="detail real-detail">${businessPhotos(r)}<div class="business-summary"><div class="detail-kicker"><span class="eyebrow">${esc(r.sector)} · HELPU LOCAL</span><button type="button" class="save detail-save" data-save="${esc(r.id)}" aria-label="Salvar ${esc(r.name)}" aria-pressed="${saved.includes(r.id)}">${icon('heart')}</button></div><h1>${r.logo?`<img class="business-logo detail-business-logo" src="${esc(r.logo)}" alt="${esc(r.name)}">`:esc(r.name)}</h1><p class="muted local-lines">${esc(r.description)}</p>${sectorActions(r)}</div></section>${r.address||r.hours||r.offer?`<section class="business-information">${r.address?`<div><h2>Onde atendemos</h2><p class="local-lines">${esc(r.address)}</p></div>`:''}${r.hours?`<div><h2>Horários</h2><p class="local-lines">${esc(r.hours)}</p></div>`:''}${r.offer?`<div><h2>Mais sobre o negócio</h2><p class="local-lines">${esc(r.offer)}</p></div>`:''}</section>`:''}${sectorCatalog(r)}${r.events?.length?'<section><div class="section-head"><h2>Próximos eventos</h2></div>'+cards(eventCards([r]))+'</section>':''}`;recordMetric(r.id,'view');}catch(e){main.innerHTML=back()+'<p role="alert">'+esc(e.message)+'</p>';}}
async function loadSaved(){try{saved=favorites();const rows=await publicBusinesses(),real=[...rows.map(realCard),...eventCards(rows)];if(location.hash.split('?')[0]!=='#/salvos')return;const el=document.querySelector('#saved-cards');if(el){const selected=real.filter(i=>saved.includes(i.id));el.innerHTML=selected.length?cards(selected):'<div class="empty saved-empty"><span class="empty-symbol">♡</span><h2>Seus próximos favoritos.</h2><p>Toque no coração de um negócio ou evento para encontrá-lo aqui. Anúncios retirados do ar deixam de aparecer.</p><a class="primary" href="/local">Encontrar algo especial ↗</a></div>';}}catch{const el=document.querySelector('#saved-cards');if(el)el.innerHTML='<p>Não foi possível carregar os negócios salvos. Atualize a página para tentar novamente.</p>';}}
function eventCards(rows){return rows.flatMap(r=>(r.events||[]).map(e=>({id:'event:'+e.id,real:true,href:'/local#/evento?empresa='+encodeURIComponent(r.id)+'&id='+encodeURIComponent(e.id),image:e.image||r.photos?.[0],cat:'Eventos',title:e.name,name:e.name,desc:e.date.split('-').reverse().join('/')+' · '+e.time+' · '+r.name,cta:'Ver evento',sort:e.date+'T'+e.time}))).sort((a,b)=>a.sort.localeCompare(b.sort));}
async function addRealBusinesses(){const hash=location.hash;if(hash&&hash!=='#/'&&!hash.startsWith('#/categoria'))return;const params=new URLSearchParams(hash.split('?')[1]||''),category=params.get('tipo')||'Para você',norm=s=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase(),q=norm(params.get('q')||'');try{const rows=await publicBusinesses();if(location.hash!==hash)return;const businesses=rows.filter(r=>(category==='Para você'||r.sector===category)&&norm(r.name+' '+r.description+' '+r.sector).includes(q)),events=eventCards(rows).filter(e=>norm(e.name+' '+e.desc).includes(q));const list=category==='Eventos'?events:businesses.map(realCard);document.querySelector('#real-businesses').innerHTML='<div class="section-head"><h2>'+(category==='Eventos'?'Agenda da cidade':'Para descobrir hoje')+'</h2><span class="muted">'+list.length+' resultados</span></div>'+cards(list)+(category==='Para você'&&events.length?'<div class="section-head"><h2>Próximos eventos</h2><a href="/local#/categoria?tipo=Eventos">Ver agenda ↗</a></div>'+cards(events):'');}catch{if(location.hash===hash)document.querySelector('#real-businesses').innerHTML='<p role="alert">Não foi possível carregar a página. Atualize para tentar novamente.</p>';}}
async function loadEvent(businessId,eventId){const hash=location.hash;try{const rows=await publicBusinesses();if(location.hash!==hash)return;const r=rows.find(b=>b.id===businessId),e=r?.events?.find(e=>e.id===eventId);if(!e){main.innerHTML=back()+'<div class="empty"><h1>Evento indisponível ou encerrado.</h1><a href="/local#/categoria?tipo=Eventos">Ver agenda ↗</a></div>';return;}document.title=e.name+' · Helpu Local';sectorActions(r);main.innerHTML=back()+`<section class="detail real-detail">${businessPhotos({...r,name:e.name,photos:e.image?[e.image]:r.photos})}<div class="business-summary"><span class="eyebrow">EVENTO · ${esc(r.name)}</span><h1>${esc(e.name)}</h1><p class="price">${esc(e.date.split('-').reverse().join('/'))} · ${esc(e.time)}</p><p class="helper">Horário de Brasília${e.endDate?' · Até '+esc(e.endDate.split('-').reverse().join('/'))+' às '+esc(e.endTime):''}</p><p>${esc(e.venue)}</p><p class="local-lines">${esc(e.description)}</p><div class="panel"><h2>${e.priceCents==null?'Ingresso sob consulta':e.priceCents===0?'Entrada gratuita':(e.priceCents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+' por pessoa'}</h2><p class="local-lines">${esc(e.conditions||'Consulte as condições com o organizador.')}</p><button class="primary" data-request-type="inscricao" data-event-id="${esc(e.id)}">Solicitar participação ↗</button><p class="helper">O organizador confirma disponibilidade e condições. O envio não emite ingresso nem cobra pagamento.</p></div><a href="/local#/negocio?id=${encodeURIComponent(r.id)}">Conhecer ${esc(r.name)} ↗</a></div></section>`;recordMetric(r.id,'view');}catch(e){if(location.hash===hash)main.innerHTML=back()+'<p role="alert">'+esc(e.message)+'</p>';}}
window.addEventListener('hashchange',addRealBusinesses);addRealBusinesses();

function businessPhotos(r){return r.photos?.length?`<div class="business-visual"><a class="business-main-photo" href="${esc(r.photos[0])}" target="_blank" rel="noopener" aria-label="Ampliar foto de ${esc(r.name)}"><img src="${esc(r.photos[0])}" alt="${esc(r.name)}" fetchpriority="high"></a>${r.photos.length>1?`<div class="business-thumbnails" aria-label="Fotos do negócio">${r.photos.map((url,i)=>`<button type="button" data-business-photo="${esc(url)}" aria-label="Ver foto ${i+1}" aria-pressed="${i===0}"><img src="${esc(url)}" alt="" loading="lazy"></button>`).join('')}</div>`:''}</div>`:'<div class="business-visual"><div class="business-photo-empty"><span>helpu<span class="eyebrow">LOCAL</span></span><p>Fotos em breve</p></div></div>';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-business-photo]');if(!button)return;const visual=button.closest('.business-visual'),link=visual.querySelector('.business-main-photo');link.href=button.dataset.businessPhoto;link.querySelector('img').src=button.dataset.businessPhoto;visual.querySelectorAll('[data-business-photo]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});
function businessCatalog(r){return r.catalog?.length?`<section class="business-catalog"><h2>Produtos e serviços</h2>${r.catalog.map(x=>`<article class="panel"><h3>${esc(x.name)}</h3><p class="local-lines">${esc(x.description)}</p><p class="price">${x.priceCents==null?'Sob consulta':(x.priceCents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</p>${x.available?`<a data-business-whatsapp="${esc(r.id)}" class="text-link" href="https://wa.me/${encodeURIComponent(r.phone)}?text=${encodeURIComponent('Olá! Vi '+x.name+' na Helpu Local e gostaria de mais informações.')}" target="_blank" rel="noopener">Tenho interesse ↗</a>`:'<span class="muted">Indisponível no momento</span>'}</article>`).join('')}<p class="helper">Disponibilidade e condições finais são confirmadas diretamente com a empresa.</p></section>`:'';}

function recordMetric(businessId,type){fetch('/api/local/metric',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId,type}),keepalive:true}).catch(()=>{});}
document.addEventListener('click',e=>{const a=e.target.closest('[data-business-whatsapp]');if(a)recordMetric(a.dataset.businessWhatsapp,'whatsapp');});
function leadForm(r){return `<form id="business-lead" class="panel" data-business="${esc(r.id)}" data-phone="${esc(r.phone)}" data-key="${crypto.randomUUID()}"><h2>Conte o que você precisa.</h2><div class="fields"><label>Seu nome<input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><label>Seu WhatsApp com DDD<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label></div><label>Seu pedido<textarea name="message" required minlength="3" maxlength="2000"></textarea></label><div hidden><input name="website" tabindex="-1" autocomplete="off"></div><label class="consent"><input type="checkbox" name="consent" required> Autorizo ${esc(r.name)} a retornar sobre este pedido pelo WhatsApp.</label><p class="helper">Seus dados serão enviados a este negócio. <a href="/privacidade.html" target="_blank" rel="noopener">Privacidade ↗</a></p><p role="alert"></p><button class="primary">Enviar pedido de contato</button><a data-business-whatsapp="${esc(r.id)}" class="business-direct-contact text-link" href="https://wa.me/${encodeURIComponent(r.phone)}" target="_blank" rel="noopener">Prefere conversar agora? Abrir WhatsApp ↗</a></form>`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='business-lead')return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(f)),r=await fetch('/api/local/lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,consent:f.elements.consent.checked,businessId:f.dataset.business,requestKey:f.dataset.key})}),d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível enviar.');const message='Olá! Enviei um pedido pela Helpu Local. Meu nome é '+values.name+'. '+values.message;f.innerHTML=`<h2>Pedido registrado!</h2><p>A empresa poderá acompanhar seu pedido no portal. Se preferir, envie também pelo WhatsApp.</p><a data-business-whatsapp="${esc(f.dataset.business)}" class="primary" href="https://wa.me/${encodeURIComponent(f.dataset.phone)}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">Continuar no WhatsApp ↗</a>`;}catch(err){f.querySelector('[role=alert]').textContent=err.message;b.disabled=false;}});

let toastTimer;
function showLocalToast(message){const el=document.querySelector('#toast');if(!el)return;el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3500);}
function syncSavedButtons(){document.querySelectorAll('[data-save]').forEach(button=>{const active=saved.includes(button.dataset.save);button.setAttribute('aria-pressed',String(active));button.innerHTML=icon('heart');});}
function updateSavedNavigation(){document.querySelectorAll('[data-saved-count]').forEach(el=>{el.textContent=String(saved.length);el.hidden=!saved.length;});document.querySelectorAll('header nav a,.mobile-nav a').forEach(a=>{const current=(a.hash&&a.hash===location.hash)||(!a.hash&&a.pathname==='/local'&&(!location.hash||location.hash==='#/')); a.toggleAttribute('aria-current',!!current);if(current)a.setAttribute('aria-current','page');});}
function refreshSaved(){saved=favorites();syncSavedButtons();updateSavedNavigation();if(location.hash.split('?')[0]==='#/salvos')loadSaved();}
window.addEventListener('storage',e=>{if(e.key===savedKey||e.key===null)refreshSaved();});window.addEventListener('pageshow',refreshSaved);window.addEventListener('focus',refreshSaved);
